    #[test]
    fn library_sources_can_be_deselected_independently() {
        let owned = LibraryEntry {
            playtime: 0,
            acquired: None,
            appid: 1,
            name: "Owned".into(),
            installed: true,
            on_disk: true,
            steam: true,
            family: false,
            update: None,
            store: None,
            cover: String::new(),
            size: None,
            publishers: Vec::new(),
            developers: Vec::new(),
        };
        let family = LibraryEntry {
            playtime: 0,
            acquired: None,
            appid: 2,
            name: "Family".into(),
            installed: false,
            on_disk: false,
            steam: true,
            family: true,
            update: None,
            store: None,
            cover: String::new(),
            size: None,
            publishers: Vec::new(),
            developers: Vec::new(),
        };
        let disk_only = LibraryEntry {
            playtime: 0,
            acquired: None,
            appid: 3,
            name: "Disk only".into(),
            installed: true,
            on_disk: true,
            steam: false,
            family: false,
            update: None,
            store: None,
            cover: String::new(),
            size: None,
            publishers: Vec::new(),
            developers: Vec::new(),
        };
        // Un jeu de boutique n'appartient à aucune source Steam : il suit sa
        // propre pastille.
        let epic = LibraryEntry {
            playtime: 0,
            acquired: None,
            appid: 4,
            name: "Epic".into(),
            installed: false,
            on_disk: false,
            steam: false,
            family: false,
            update: None,
            store: Some(lapinux_core::stores::Store::Epic),
            cover: "https://cdn/epic.jpg".into(),
            size: Some(3_000_000_000),
            publishers: Vec::new(),
            developers: Vec::new(),
        };
        let mut sources: SourceFilter = SourceFilter::default();
        assert!(sources.keeps(&owned));
        assert!(sources.keeps(&family));
        assert!(sources.keeps(&disk_only));

        sources.disk = false;
        assert!(sources.keeps(&owned));
        assert!(!sources.keeps(&disk_only));

        sources.steam = false;
        assert!(sources.keeps(&family));
        assert!(!sources.keeps(&owned));

        sources.family = false;
        // La source Epic reste active : la bibliothèque n'est pas vide.
        assert!(sources.any());
        assert!(!sources.keeps(&family));
        assert!(sources.keeps(&epic));

        for on in sources.stores.iter_mut() {
            *on = false;
        }
        assert!(!sources.any());
        assert!(!sources.keeps(&epic));
    }

